XACT.mp_cumbre = [L2('🏔 Foto en la cumbre del Huayna Picchu', '🏔 Photo at the Huayna Picchu summit'), 'run', () => { const P = G.P, day = Math.floor(typeof calDay === 'function' ? calDay() : G.time / 1440); stampTry('cz_huayna'); czHist('maravilla'); if (P.czHP !== day) { P.czHP = day; P.gold += 1000; markDirty(); } sfx('quest'); banner('🏔 ' + L2('¡Cumbre del Huayna Picchu!', 'Huayna Picchu summit!'), L2('Abajo, Machu Picchu entre las nubes. +1.000 de oro (una vez al día).', 'Below, Machu Picchu among the clouds. +1,000 gold (once a day).')); }];
