WORLD_DRAW.push((cx, cy) => { if (ACT.k !== 'v8_arriero') return; const B = ACT; B.ll.forEach(e => { const x = e.x - cx, y = e.y - cy - 30; ctx.fillStyle = '#c8302a'; ctx.fillRect(x - 6, y, 12, 5); ctx.fillStyle = '#ffd040'; ctx.fillRect(x - 6, y + 2, 12, 1); }); if (B.sat) drawTxt('💢', B.sat.x - cx, B.sat.y - 44 - cy, '#ffffff', 11); });
{ const _off = v8Off; v8Off = function () { if (ACT.k === 'v8_arriero' && G.P) G.P.wp = null; return _off.apply(this, arguments); }; }

// ---------- tintorera de Pisac: tres ollas de tinte natural a la temperatura justa ----------
v8Job('tintorera', 'cusco', '🧶', 'Tintorera de Pisac', 'Pisac dyer', M => [CZ_PI.mx1 + 8, CZ_PI.my0 + 4], [8, 6], ['pe', 'f', 3, { head: 'c_cz_montera', body: 'c_cz_lliclla', legs: 'c_cz_pollera_azul' }],
  'Cochinilla para el rojo, q\'olle para el amarillo, añil para el azul. Si hierve de más, el color se apaga.', 'Cochineal for red, q\'olle for yellow, indigo for blue. If it boils too much, the colour fades.',
  'Tres ollas tiñen la lana. Cada olla debe estar en la franja verde de temperatura para que avance su tinte. El fuego se apaga poco a poco: toma leña del montón (⚔) y échala en una olla (⚔) para subirla. Si pasa de la franja, la lana se quema y pierde avance. Termina las tres. Recompensas: lliclla y polleras.', 'Three pots dye the wool. Each pot must be in the green temperature band for its dye to progress. The fire dies down little by little: take firewood from the pile (⚔) and put it in a pot (⚔) to heat it up. If it goes past the band, the wool burns and loses progress. Finish all three. Rewards: lliclla and pollera skirts.',
  'Tintes naturales (Pisac)', 'Natural dyes (Pisac)', CZ_PI_NO_ATK);
const TIN_C = [['#c8203a', L2('Cochinilla', 'Cochineal')], ['#e8c020', 'Q\'olle'], ['#2a4ab8', L2('Añil', 'Indigo')]];
V8_GO.tintorera = A => { const P = G.P; P.x = A.px; P.y = A.py + 24; const pots = TIN_C.map((c, i) => ({ x: A.px - 44 + i * 44, y: A.py - 6, temp: 40 + i * 8, prog: 0, c: c[0], n: c[1] }));
  Object.assign(ACT, { k: 'v8_tintorera', pots, pile: { x: A.px + 70, y: A.py + 22 }, wood: 0, t: 90, burnt: 0, onAtk: () => { const B = ACT, P = G.P; if (aDist(P, B.pile) < 22) { if (B.wood) { toast(L2('Ya llevas leña', 'You are already carrying wood'), 'warn'); return true; } B.wood = 1; sfx('ui'); return true; }
      const pt = B.pots.find(q => aDist(P, q) < 24); if (pt) { if (!B.wood) { toast(L2('Trae leña del montón', 'Bring wood from the pile'), 'warn'); return true; } B.wood = 0; pt.temp = Math.min(130, pt.temp + 32); sfx('hit'); for (let k = 0; k < 8; k++) part(pt.x, pt.y + 4, { vz: 40, vx: v8Rnd(-20, 20), g: -20, life: 0.6, c: '#ff8a2a', s: 2 }); } return true; } });
  banner('🧶 ' + L2('¡A teñir!', 'Let\'s dye!'), L2('Mantén las tres ollas en la franja verde con leña (⚔).', 'Keep all three pots in the green band with firewood (⚔).')); };
V33_TICKS.push(dt => { if (ACT.k !== 'v8_tintorera') return; dt = Math.min(0.05, dt || 0.016); const B = ACT; B.t -= dt;
  for (const q of B.pots) { if (q.prog >= 1) continue; q.temp = Math.max(0, q.temp - 6.5 * dt); if (q.temp >= 60 && q.temp <= 85) q.prog = Math.min(1, q.prog + dt / 22 * (1 + jobPerkSum('v8tintorera') / 100)); else if (q.temp > 95) { q.prog = Math.max(0, q.prog - dt * 0.06); if (Math.random() < 0.05) { B.burnt++; floatText(q.x, q.y - 30, L2('¡Se quema!', 'Burning!'), '#ff8a8a'); } }
    if (Math.random() < 0.15) part(q.x + v8Rnd(-6, 6), q.y - 10, { vz: 20, g: -30, life: 0.8, c: q.temp > 95 ? 'rgba(60,60,60,0.6)' : q.c, s: 2 }); if (q.prog >= 1) { sfx('coin'); floatText(q.x, q.y - 34, '🧶 ' + q.n, q.c); } }
  const done = B.pots.filter(q => q.prog >= 1).length; v8Hud(`🧶 ${done}/3 · ${B.wood ? '🪵' : L2('sin leña', 'no wood')} · ${Math.ceil(B.t)} s`);
  if (done >= 3 || B.t <= 0) { const sc = B.pots.reduce((s, q) => s + q.prog, 0); v8Pay('tintorera', 80 + Math.round(sc * 280) + (done >= 3 ? 200 : 0), 20 + sc * 25, done + L2('/3 madejas teñidas', '/3 skeins dyed')); } });
V8_UNDER.push((cx, cy) => { if (ACT.k !== 'v8_tintorera') return; const B = ACT; for (const q of B.pots) { const x = q.x - cx, y = q.y - cy; ctx.fillStyle = '#ff7a1a'; ctx.beginPath(); ctx.ellipse(x, y + 8, 10 + Math.sin(G.t * 9) * 1, 4, 0, 0, 7); ctx.fill(); ctx.fillStyle = '#3a3a40'; ctx.beginPath(); ctx.ellipse(x, y, 13, 10, 0, 0, 7); ctx.fill(); ctx.fillStyle = q.c; ctx.beginPath(); ctx.ellipse(x, y - 5, 10, 4, 0, 0, 7); ctx.fill(); }
  const p = B.pile; ctx.fillStyle = '#7a4a22'; for (let k = 0; k < 6; k++) ctx.fillRect(p.x - 12 + (k % 3) * 8 - cx, p.y - 6 + Math.floor(k / 3) * 5 - cy, 8, 4); });
WORLD_DRAW.push((cx, cy) => { if (ACT.k !== 'v8_tintorera') return; const B = ACT; for (const q of B.pots) { const x = q.x - 4 - cx, y = q.y - 48 - cy; ctx.fillStyle = 'rgba(0,0,0,0.6)'; ctx.fillRect(x, y, 8, 30); const kk = 30 / 130; ctx.fillStyle = 'rgba(58,192,74,0.6)'; ctx.fillRect(x, y + 30 - 85 * kk, 8, 25 * kk); ctx.fillStyle = q.temp > 95 ? '#ff4a3a' : q.temp >= 60 ? '#7aff8a' : '#9ad0ff'; ctx.fillRect(x + 1, y + 30 - Math.min(130, q.temp) * kk - 1, 6, 2);
    ctx.fillStyle = '#ffd040'; ctx.fillRect(x - 6, y + 32, 20 * q.prog, 2); } if (B.wood) { const P = G.P; ctx.fillStyle = '#7a4a22'; ctx.fillRect(P.x - cx - 6, P.y - cy - 34, 12, 4); } });

// ---------- Lupa › Sistemas ----------
if (typeof GSIS !== 'undefined') GSIS.unshift(['cusco529', '🦙 ' + L2('Cusco, Valle Sagrado y Machu Picchu (5.29)', 'Cusco, Sacred Valley and Machu Picchu (5.29)'), () => [
  L2('Cómo llegar: Lima → bus a Trujillo (5.000) → Tren Andino a Cusco desde la Terminal de Trujillo (8.000). Desde la estación de Cusco sale el tren a Machu Picchu (Aguas Calientes, 3.000). En el tren vas sentado mirando por la ventana (o «Llegar ya»).', 'How to get there: Lima → bus to Trujillo (5,000) → Andean Train to Cusco from the Trujillo Terminal (8,000). The train to Machu Picchu (Aguas Calientes, 3,000) leaves from Cusco station. On the train you sit looking out of the window (or «Arrive now»).'),
  L2('Cusco: Plaza de Armas con la Catedral, la Compañía de Jesús, la fuente del Inca, banderas y portales; San Blas (casas blancas de puertas azules y la tienda de ropa andina); la piedra de los 12 ángulos en Hatun Rumiyoc; Qorikancha; Mercado de San Pedro; Sacsayhuamán con sus muros en zigzag, el Cristo Blanco y el establo de llamas.', 'Cusco: Main Square with the Cathedral, the Church of the Society of Jesus, the Inca fountain, flags and arcades; San Blas (white houses with blue doors and the Andean clothes shop); the twelve-angled stone on Hatun Rumiyoc; Qorikancha; San Pedro Market; Sacsayhuamán with its zigzag walls, the White Christ and the llama stable.'),
  L2('Valle Sagrado: Pisac (andenes y mercado de tejidos), Moray (andenes circulares) y Ollantaytambo (fortaleza en andenes). Vinicunca, la Montaña de Siete Colores, con foto en la cumbre (+800 al día). Machu Picchu: andenes, casas de piedra, plaza, Templo del Sol, Tres Ventanas, Intihuatana, y la escalada al Huayna Picchu (+1.000 al día en la cumbre).', 'Sacred Valley: Pisac (terraces and textile market), Moray (circular terraces) and Ollantaytambo (terraced fortress). Vinicunca, the Rainbow Mountain, with a summit photo (+800 a day). Machu Picchu: terraces, stone houses, plaza, Temple of the Sun, Three Windows, Intihuatana, and the climb up Huayna Picchu (+1,000 a day at the summit).'),
  L2('Soroche: subir a Vinicunca, al Huayna Picchu o por Sacsayhuamán llena la barra de altura. Quieto se recupera; si se llena te mareas y vas más lento. El mate de coca (vendedora de la Plaza de Armas, 40) lo quita y te protege 5 minutos.', 'Altitude sickness: climbing Vinicunca, Huayna Picchu or around Sacsayhuamán fills the altitude bar. It recovers while you stand still; if it fills you get dizzy and slower. Coca tea (Main Square seller, 40) removes it and protects you for 5 minutes.'),
  L2('Oficios (no dan fuerza): guía de Machu Picchu, arriero de llamas y tintorera de Pisac. Dan oro, experiencia de oficio ×3, ventajas de crítico, esquiva, vida y velocidad, y ropa andina nueva (chullo, poncho, chaleco, montera, lliclla y polleras). Toda la ropa también se vende en San Blas y se adapta a todos los cuerpos y peinados.', 'Jobs (no strength): Machu Picchu guide, llama muleteer and Pisac dyer. They give gold, ×3 job experience, crit, dodge, HP and speed perks, and new Andean clothes (chullo, poncho, vest, montera, lliclla and pollera skirts). All clothes are also sold in San Blas and fit every body and hairstyle.'),
  L2('Montura: llama de Cusco (150.000, 2,0×) en el establo de Sacsayhuamán. En Madrid, el Superdeportivo «Toro Bravo» (2.500.000, 2,4×, el más rápido). Las mascotas de Perú, México y España ahora dan un bono pequeño.', 'Mount: Cusco llama (150,000, 2.0×) at the Sacsayhuamán stable. In Madrid, the «Toro Bravo» supercar (2,500,000, 2.4×, the fastest). Peru, Mexico and Spain pets now give a small bonus.'),
  L2('Historia extra de Perú (aparte del lore principal): Libro › Historias extra. Se desbloquea visitando los lugares, con la guía de la Plaza de Armas y guiando grupos en Machu Picchu.', 'Peru extra story (apart from the main lore): Book › Extra stories. It unlocks by visiting places, with the Main Square guide and by guiding groups at Machu Picchu.')],
  () => { const P = G.P; if (P && P.map === 'cusco') return { loc: [CZ_PZ.cx, CZ_PZ.cy], t: L2('Plaza de Armas del Cusco', 'Cusco Main Square'), m: 'cusco' }; if (P && P.map === 'machupicchu') return { loc: [MP_PZ.cx, MP_PZ.cy], t: 'Machu Picchu', m: 'machupicchu' }; const T_ = G.maps.trujillo && G.maps.trujillo.czTerm; return T_ ? { loc: T_, t: L2('Tren Andino a Cusco', 'Andean Train to Cusco'), m: 'trujillo' } : { loc: [TR_TERM.x, TR_TERM.y], t: L2('Terminal de Trujillo', 'Trujillo Terminal'), m: 'trujillo' }; }]);
